"""Run FastAPI with private local settings generated by setup_local_database.py."""
import argparse
import json
import os
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--host', default='127.0.0.1', help='Use this computer LAN IP for ESP32 access')
    parser.add_argument('--port', type=int, default=8000)
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    config = root / 'artifacts' / 'backend-local' / 'runtime-env.json'
    if not config.is_file():
        parser.error('Run python tools/setup_local_database.py first.')
    os.chdir(root)
    os.environ.update(json.loads(config.read_text()))
    import uvicorn
    uvicorn.run('backend.app:app', host=args.host, port=args.port)


if __name__ == '__main__':
    main()
